              "text": "[Document context]\nTitle: vLLM torch utils configuration tests\nSource: Redwood task issue 34752\nPath: /code/vllm/tests/utils_/test_torch_utils.py\nWorkspace: task/jamal-vllm-34752-20260816\n\n# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\nfrom types import SimpleNamespace\n\nimport pytest\nimport torch\n\nfrom vllm.utils.torch_utils import (\n    common_broadcastable_dtype,\n    current_stream,\n    is_lossless_cast,\n    resolve_kv_cache_dtype_string,\n)\n\ndef _model_config_with_kv_cache_metadata(kv_cache_quant_algo=None):\n    quantization_config = {\"quant_method\": \"modelopt\"}\n    if kv_cache_quant_algo is not None:\n        quantization_config[\"kv_cache_quant_algo\"] = kv_cache_quant_algo\n    hf_config = SimpleNamespace(quantization_config=quantization_config)\n    return SimpleNamespace(hf_config=hf_config)\n\n@pytest.mark.parametrize(\"requested_dtype\", [\"auto\", \"fp8\", \"fp8_e4m3\"])\ndef test_resolve_kv_cache_dtype_uses_checkpoint_metadata(requested_dtype):\n    model_config = _model_config_with_kv_cache_metadata(\"fp8\")\n\nassert resolve_kv_cache_dtype_string(requested_dtype, model_config) == \"fp8_e4m3\"\n\n@pytest.mark.parametrize(\"requested_dtype\", [\"auto\", \"bfloat16\"])\ndef test_resolve_kv_cache_dtype_without_checkpoint_metadata(requested_dtype):\n    model_config = _model_config_with_kv_cache_metadata()\n\nassert (\n        resolve_kv_cache_dtype_string(requested_dtype, model_config)\n        == requested_dtype\n    )\n\ndef test_resolve_kv_cache_dtype_rejects_conflicting_override():\n    model_config = _model_config_with_kv_cache_metadata(\"fp8\")\n\nwith pytest.raises(ValueError, match=\"Remove --kv-cache-dtype\"):\n        resolve_kv_cache_dtype_string(\"bfloat16\", model_config)\n\ndef test_resolve_kv_cache_dtype_rejects_unsupported_checkpoint_metadata():\n    model_config = _model_config_with_kv_cache_metadata(\"int8\")\n\nwith pytest.raises(ValueError, match=\"Unsupported checkpoint kv_cache_quant_algo\"):\n        resolve_kv_cache_dtype_string(\"auto\", model_config)",
