_aux_stream: torch.cuda.Stream | None = None

def aux_stream() -> torch.cuda.Stream | None:
    """
    Ensures aux_stream is initialized only once
    """
    global _aux_stream

from vllm.platforms import current_platform

if _aux_stream is None and current_platform.is_cuda_alike():
        _aux_stream = torch.cuda.Stream()

return _aux_stream

def weak_ref_tensor(tensor: Any) -> Any:
    """
    Create a weak reference to a tensor.
    The new tensor will share the same data as the original tensor,
    but will not keep the original tensor alive.
    This ignores 0-size tensors as those don't allocate any memory.
    """
    if isinstance(tensor, torch.Tensor) and tensor.numel() > 0:
        return torch.ops._C.weak_ref_tensor(tensor)
    else:
        return tensor

def weak_ref_tensors(
    tensors: torch.Tensor
    | list[torch.Tensor]
    | tuple[torch.Tensor]
    | IntermediateTensors,
) -> torch.Tensor | list[Any] | tuple[Any] | Any:
    """
    Convenience function to create weak references to tensors,
    for single tensor, list of tensors or tuple of tensors.
    """
    if isinstance(tensors, torch.Tensor):
        return weak_ref_tensor(tensors)
    if isinstance(tensors, list):
        return [weak_ref_tensor(t) for t in tensors]
    if isinstance(tensors, tuple):
        return tuple(weak_ref_tensor(t) for t in tensors)

# For IntermediateTensors used in pipeline parallelism
    from vllm.sequence import IntermediateTensors

if isinstance(tensors, IntermediateTensors):
        ret = IntermediateTensors(
            {key: weak_ref_tensor(val) for key, val in tensors.tensors.items()}
        )
        return ret
    raise ValueError("Invalid type for tensors")","content_hash":"0c6c33c74c5edbeb65d5b51c02a2317f988926fba3f57bde3d6c8a440523fd8f","chunk_metadata":{"ordinal":19,"document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","workspace":"task/jamal-vllm-34752-20260816","team":""}}},"conflict_id":null,"change_id":"qdrant:70022073b2576562ad6c436c"},{"table":"knowledge","key":{"id":"enterprise_97b36da892839ccc46c62291:00020"},"change":"modified","before":{"id":"enterprise_97b36da892839ccc46c62291:00020","vector":{"bm25":{"indices":[70186382,250826051,390626577,448220673,454222729,464747871,470013406,495859784,560628486,648501015,757424159,766710245,772165269,806276788,926244272,1030514789,1039654807,1263925004,1264846464,1331432587,1430125705,1515372845,1519078073,1717991430,1728513269,1853176582,2028263370,2068289407,2068519488],"values":[1.4197127,2.0153873,1.7257545,1.4197127,1.4197127,1.7257545,1.7257545,2.0398407,1.934232,1.4197127,1.7257545,1.4197127,1.4197127,1.7257545,1.4197127,1.934232,1.7257545,1.4197127,2.0153873,1.7257545,1.4197127,1.8593595,1.4197127,2.095309,1.7257545,1.4197127,1.4197127,1.4197127,1.4197127]}},"payload":{"text":"[Document context]
