              "text": "[Document context]\nTitle: vLLM KV-cache dtype resolver\nSource: Redwood task issue 34752\nPath: /code/vllm/vllm/utils/torch_utils.py\nWorkspace: task/jamal-vllm-34752-20260816\n\nelse:\n                raise ValueError(\n                    \"Unsupported checkpoint kv_cache_quant_algo \"\n                    f\"{kv_algo!r}. Supported values are: \"\n                    f\"{list(MODELOPT_TO_VLLM_KV_CACHE_DTYPE_MAP)}. \"\n                    \"Use a checkpoint with supported KV-cache metadata.\"\n                )\n    return None\n\ndef get_kv_cache_quant_algo_dtype(quant_cfg: dict[str, Any]) -> torch.dtype | None:\n    \"\"\"Get the KV cache quantization algorithm dtype from the quantization config.\"\"\"\n    kv_algo_str = get_kv_cache_quant_algo_string(quant_cfg)\n    if kv_algo_str is not None and kv_algo_str != \"auto\":\n        # Only convert if we have a valid dtype string (not \"auto\" fallback)\n        return STR_DTYPE_TO_TORCH_DTYPE[kv_algo_str]\n    return None\n\ndef resolve_kv_cache_dtype_string(\n    kv_cache_dtype: str, model_config: ModelConfig\n) -> str:\n    \"\"\"Resolve 'auto' kv_cache_dtype to the actual string value from model config.\n    Returns the resolved cache_dtype string.\n    \"\"\"\n    hf_cfg = getattr(model_config, \"hf_config\", None)\n    if hf_cfg is not None:\n        quant_cfg = getattr(hf_cfg, \"quantization_config\", None)\n        if quant_cfg is not None:\n            kv_algo_str = get_kv_cache_quant_algo_string(quant_cfg)\n            if kv_algo_str is not None:\n                requested_dtype = (\n                    \"fp8_e4m3\" if kv_cache_dtype == \"fp8\" else kv_cache_dtype\n                )\n                if requested_dtype not in (\"auto\", kv_algo_str):\n                    raise ValueError(\n                        f\"--kv-cache-dtype {kv_cache_dtype!r} conflicts with \"\n                        \"checkpoint kv_cache_quant_algo, which requires \"\n                        f\"{kv_algo_str!r}. Remove --kv-cache-dtype or set it \"\n                        f\"to 'auto' or {kv_algo_str!r}.\"\n                    )\n                return kv_algo_str\n\nreturn kv_cache_dtype",
