              "text": "[Document context]\nTitle: vLLM KV-cache dtype resolver\nSource: Redwood task issue 34752\nPath: /code/vllm/vllm/utils/torch_utils.py\nWorkspace: task/jamal-vllm-34752-20260816\n\n* scale_dim // full_dim\n    s2_s = kv_side.stride(2) * scale_dim // full_dim\n    scale_shape = (num_pages, dim_1, dim_2, scale_dim)\n    scale_strides = (page_bytes, s1_s, s2_s, 1)\n\nbase = kv_side.storage_offset()\n    data = torch.as_strided(kv_side, data_shape, data_strides, storage_offset=base)\n    scale = torch.as_strided(\n        kv_side, scale_shape, scale_strides, storage_offset=base + data_per_kv\n    ).view(torch.float8_e4m3fn)\n\nreturn data, scale\n\ndef create_kv_caches_with_random_flash(\n    num_blocks: int,\n    block_size: int,\n    num_layers: int,\n    num_heads: int,\n    head_size: int,\n    cache_dtype: str | torch.dtype | None,\n    model_dtype: str | torch.dtype | None = None,\n    seed: int | None = None,\n    device: str | None = \"cuda\",\n    cache_layout: str | None = \"NHD\",\n) -> tuple[list[torch.Tensor], list[torch.Tensor]]:\n    set_random_seed(seed)\n\ndtype = get_kv_cache_torch_dtype(cache_dtype, model_dtype)\n    generic_kv_cache_shape = (num_blocks, 2, block_size, num_heads, head_size)\n    assert cache_layout in (\"NHD\", \"HND\")\n    stride_order = (0, 1, 2, 3, 4) if cache_layout == \"NHD\" else (0, 1, 3, 2, 4)\n\nkv_cache_allocation_shape = tuple(generic_kv_cache_shape[i] for i in stride_order)\n    scale = head_size**-0.5\n\nkey_caches: list[torch.Tensor] = []\n    value_caches: list[torch.Tensor] = []",
