def _get_precision_level(dtype: torch.dtype) -> int:
    # NOTE: Complex dtypes return `is_floating_point=False`
    return (dtype != torch.bool) + dtype.is_floating_point + dtype.is_complex * 2

def is_lossless_cast(src_dtype: torch.dtype, tgt_dtype: torch.dtype):
    """
    Test whether it is lossless to cast a tensor from
    `src_dtype` to `tgt_dtype`.
    """
    if src_dtype == tgt_dtype:
        return True

src_level = _get_precision_level(src_dtype)
    tgt_level = _get_precision_level(tgt_dtype)

if src_level < tgt_level:
        return True
    if src_level > tgt_level:
        return False

# Compare integral types
    if not src_dtype.is_floating_point and not src_dtype.is_complex:
        src_info = torch.iinfo(src_dtype)
        tgt_info = torch.iinfo(tgt_dtype)
        return src_info.min >= tgt_info.min and src_info.max <= tgt_info.max

# Compare floating-point types
    src_info = torch.finfo(src_dtype)
    tgt_info = torch.finfo(tgt_dtype)
    return (
        src_info.min >= tgt_info.min
        and src_info.max <= tgt_info.max
        and src_info.resolution >= tgt_info.resolution
    )

def common_broadcastable_dtype(dtypes: Collection[torch.dtype]):
    """
    Get the common `dtype` where all of the other `dtypes` can be
    cast to it without losing any information.
    """
    return max(
        dtypes,
        key=lambda dtype: sum(is_lossless_cast(dt, dtype) for dt in dtypes),
    )","content_hash":"6a6186ca674277e7b76646c45c8f8847698929bdd9c7eb9f34dbb08812924d5d","chunk_metadata":{"ordinal":5,"document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","workspace":"task/jamal-vllm-34752-20260816","team":""}}},"conflict_id":null,"change_id":"qdrant:b4a3937471f6e55c7203b5c8"},{"table":"knowledge","key":{"id":"enterprise_97b36da892839ccc46c62291:00006"},"change":"modified","before":{"id":"enterprise_97b36da892839ccc46c62291:00006","vector":{"bm25":{"indices":[70186382,117848935,176587294,250826051,330588669,362932159,390626577,443994268,448220673,454222729,455026286,465629622,491396510,575861184,708020707,716765060,757424159,766710245,772165269,806276788,824480995,888000370,897065139,921197322,926244272,930975236,1039654807,1108634416,1263925004,1331432587,1372240236,1430125705,1432958018,1515372845,1519078073,1595981574,1728513269,1784332343,1830646559,1853176582,1882140086,1948319995,2021799277,2047970710],"values":[1.3882179,1.3882179,1.702282,2.0046272,1.9194002,1.9194002,1.9194002,1.3882179,1.3882179,1.3882179,1.3882179,1.969644,1.702282,1.3882179,1.3882179,1.3882179,1.702282,1.3882179,1.3882179,1.702282,1.3882179,1.3882179,1.3882179,1.702282,1.3882179,1.702282,1.3882179,1.969644,1.3882179,1.702282,1.3882179,1.702282,1.3882179,1.3882179,1.3882179,1.702282,1.702282,1.9194002,1.3882179,1.3882179,1.702282,1.3882179,1.702282,1.3882179]}},"payload":{"chunk_metadata":{"connector":"codebase","document_path":"/code/vllm/vllm/utils/torch_utils.py","language":"py","ordinal":6,"repository":"vllm","workspace":"vllm","document_kind":"source"},"ordinal":6,"content_hash":"368d595552ee0beeaba9888fa758e1554688c8dee47255d00372e758b813e1a5","text":"[Document context]
