algorithm string from the quantization config.

Maps various FP8 format names to vLLM's standard cache dtype strings.
    Returns None if no kv_cache_quant_algo is specified.
    Raises ValueError if checkpoint metadata requests an unsupported format.
    """
    # Mapping from model config values to vLLM cache_dtype strings

quant_method = quant_cfg.get("quant_method", "")
    if quant_method.startswith("modelopt"):
        quantization_inner = quant_cfg.get("quantization", quant_cfg)
        # Check if quant config is specified and use kv cache quant algo
        kv_algo = (
            quantization_inner.get("kv_cache_scheme")
            or quant_cfg.get("kv_cache_scheme")
            or quantization_inner.get("kv_cache_quant_algo")
            or quant_cfg.get("kv_cache_quant_algo")
        )
        if isinstance(kv_algo, dict):
            if (
                kv_algo.get("dynamic") is False
                and kv_algo.get("num_bits") == 8
                and kv_algo.get("type") == "float"
            ):
                kv_algo = "fp8"
            elif kv_algo.get("num_bits") == 4 and kv_algo.get("type") == "float":
                kv_algo = "nvfp4"
            else:
                raise ValueError(
                    "Unsupported checkpoint kv_cache_quant_algo "
                    f"{kv_algo!r}. Supported values are: "
                    f"{list(MODELOPT_TO_VLLM_KV_CACHE_DTYPE_MAP)}. "
                    "Use a checkpoint with supported KV-cache metadata."
                )
        if isinstance(kv_algo, str):
            kv_algo_lower = kv_algo.lower()

# Try to map to vLLM's standard format
            if kv_algo_lower in MODELOPT_TO_VLLM_KV_CACHE_DTYPE_MAP:
                return MODELOPT_TO_VLLM_KV_CACHE_DTYPE_MAP[kv_algo_lower]
            else:
                raise ValueError(
                    "Unsupported checkpoint kv_cache_quant_algo "
                    f"{kv_algo!r}. Supported values are: "
                    f"{list(MODELOPT_TO_VLLM_KV_CACHE_DTYPE_MAP)}. "
                    "Use a checkpoint with supported KV-cache metadata."
                )
    return None","content_hash":"b63c8804a95a4d17a0f3db95a87fe9e30bb582fef1abbc6db2f35dfd7d6005ff","chunk_metadata":{"ordinal":8,"document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","workspace":"task/jamal-vllm-34752-20260816","team":""}}},"conflict_id":null,"change_id":"qdrant:5661dd7d0bc081a999946b8e"},{"table":"knowledge","key":{"id":"enterprise_97b36da892839ccc46c62291:00009"},"change":"modified","before":{"id":"enterprise_97b36da892839ccc46c62291:00009","vector":{"bm25":{"indices":[70186382,176587294,182765111,250826051,309782534,448220673,454222729,491396510,575861184,684216227,692801909,715022825,757424159,761976698,766710245,772165269,806276788,888000370,893251777,897065139,926244272,1039654807,1054993318,1086755457,1177953192,1263925004,1300030524,1331432587,1394075432,1430125705,1432958018,1519078073,1595981574,1728513269,1751311563,1810453357,1853176582,1972195609,2046950111,2128973781],"values":[1.4662849,1.4662849,1.4662849,2.0306473,1.4662849,1.4662849,1.4662849,1.4662849,1.4662849,1.4662849,1.7597251,1.4662849,1.7597251,1.4662849,1.4662849,1.4662849,1.7597251,1.4662849,1.7597251,1.4662849,1.4662849,1.7597251,1.4662849,1.4662849,1.4662849,1.4662849,1.4662849,1.7597251,1.4662849,1.7597251,1.8855039,1.4662849,1.7597251,1.7597251,1.4662849,1.4662849,1.4662849,1.4662849,1.4662849,1.7597251]}},"payload":{"text":"[Document context]
