              "text": "[Document context]\nTitle: vLLM KV-cache dtype resolver\nSource: Redwood task issue 34752\nPath: /code/vllm/vllm/utils/torch_utils.py\nWorkspace: task/jamal-vllm-34752-20260816\n\n_random_fp8(key_value_cache, -scale, scale)\n            else:\n                raise ValueError(f\"Does not support key cache of type {cache_dtype}\")\n        key_caches.append(key_value_cache[:, 0])\n        value_caches.append(key_value_cache[:, 1])\n    return key_caches, value_caches\n\ndef create_kv_caches_with_random(\n    num_blocks: int,\n    block_size: int,\n    num_layers: int,\n    num_heads: int,\n    head_size: int,\n    cache_dtype: str | torch.dtype | None,\n    model_dtype: str | torch.dtype | None = None,\n    seed: int | None = None,\n    device: str | None = \"cuda\",\n) -> tuple[list[torch.Tensor], list[torch.Tensor]]:\n    if cache_dtype == \"fp8\" and head_size % 16:\n        raise ValueError(\n            f\"Does not support key cache of type fp8 with head_size {head_size}\"\n        )\n\nset_random_seed(seed)\n\ndtype = get_kv_cache_torch_dtype(cache_dtype, model_dtype)\n\nscale = head_size**-0.5\n    x = 16 // torch.tensor([], dtype=dtype).element_size()\n    key_cache_shape = (num_blocks, num_heads, head_size // x, block_size, x)\n    key_caches: list[torch.Tensor] = []\n    for _ in range(num_layers):\n        key_cache = torch.empty(size=key_cache_shape, dtype=dtype, device=device)\n        if cache_dtype in [\"auto\", \"half\", \"bfloat16\", \"float\"]:\n            key_cache.uniform_(-scale, scale)\n        elif cache_dtype == \"fp8\":\n            _generate_random_fp8(key_cache, -scale, scale)\n        else:\n            raise ValueError(f\"Does not support key cache of type {cache_dtype}\")\n        key_caches.append(key_cache)",
