def _generate_random_fp8(
    tensor: torch.Tensor,
    low: float,
    high: float,
) -> None:
    # NOTE(zhaoyang): Due to NaN and Inf representation for fp8 data type,
    # it may occur Inf or NaN if we directly use torch.randint
    # to generate random data for fp8 data.
    # For example, s.11111.00 in fp8e5m2 format represents Inf.
    #     | E4M3        | E5M2
    # -----|-------------|-------------------
    # Inf | N/A         | s.11111.00
    # NaN | s.1111.111  | s.11111.{01,10,11}
    from vllm import _custom_ops as ops

tensor_tmp = torch.empty_like(tensor, dtype=torch.float16)
    tensor_tmp.uniform_(low, high)
    ops.convert_fp8(tensor, tensor_tmp)
    del tensor_tmp","content_hash":"042315d443f1d2939a323d2ac05bcb45f3a1191557aa1dc0f6da337172972558","chunk_metadata":{"ordinal":6,"document_path":"/code/vllm/vllm/utils/torch_utils.py","document_kind":"source","workspace":"task/jamal-vllm-34752-20260816","team":""}}},"conflict_id":null,"change_id":"qdrant:0a14699486016a1e286448fb"},{"table":"knowledge","key":{"id":"enterprise_97b36da892839ccc46c62291:00007"},"change":"modified","before":{"id":"enterprise_97b36da892839ccc46c62291:00007","vector":{"bm25":{"indices":[21141582,70186382,104962468,131900689,182765111,192819851,250826051,309782534,448220673,454222729,455026286,491396510,516762017,575861184,650894796,692801909,716765060,757424159,766710245,772165269,806276788,818319522,867520968,867748353,893251777,897065139,921197322,926244272,1009084850,1086755457,1132748958,1174952987,1187159329,1189852164,1263925004,1276336880,1299665196,1329217313,1331432587,1369581639,1420754671,1432958018,1515372845,1519078073,1529297341,1595981574,1653414040,1662505136,1701701189,1728513269,1746366895,1751311563,1778032728,1810299979,1810453357,1830646559,1845866462,1853176582,1882140086,1932973593,2021799277,2046950111,2074315840,2078791465,2120211764,2128973781],"values":[1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.9865961,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.663811,1.3377672,1.9487889,1.663811,1.663811,1.3377672,1.3377672,1.663811,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.8109325,1.3377672,1.8109325,1.3377672,1.8109325,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.663811,1.3377672,1.3377672,1.663811,1.3377672,1.3377672,1.3377672,1.8109325,1.3377672,1.3377672,1.3377672,1.663811,1.3377672,1.8109325,1.3377672,1.3377672,1.8947015,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.3377672,1.663811,1.3377672,1.3377672,1.3377672,1.8109325]}},"payload":{"chunk_id":"enterprise_97b36da892839ccc46c62291:00007","text":"[Document context]
